LOG = []


def log(ok, metin):
    LOG.append(('PASS  ' if ok else 'FAIL  ') + metin)


def bilgi(metin):
    LOG.append('      ' + metin)


def yaz(yol, b64):
    veri = Convert.FromBase64String(b64)
    d = Path.GetDirectoryName(yol)
    if not Directory.Exists(d):
        Directory.CreateDirectory(d)
    File.WriteAllBytes(yol, veri)
    return len(veri)


def debug(metin):
    """always-available progress log in the user's TEMP folder"""
    try:
        File.AppendAllText(os.path.join(Path.GetTempPath(), 'kurulum_test_debug.log'),
                           datetime.now().strftime('%H:%M:%S ') + metin + '\r\n')
    except Exception:
        pass


def hedef_sec():
    if HEDEF:
        return HEDEF
    fb = FolderBrowserDialog()
    fb.Description = 'Select the folder where the Analysis Tracker files and the Excel file will be created'
    if str(fb.ShowDialog()) != 'OK':
        return None
    return fb.SelectedPath


def dosyalari_yaz(hedef):
    for rel in sorted(PAYLOAD):
        yol = os.path.join(hedef, rel.replace('/', os.sep))
        try:
            n = yaz(yol, ''.join(PAYLOAD[rel]))
            log(True, 'file written: %s (%d bytes)' % (yol, n))
        except Exception as e:
            log(False, 'file %s: %s' % (yol, e))
    # write test: can we also delete/rename in that folder?
    try:
        t = os.path.join(hedef, '_yazma_testi.tmp')
        File.WriteAllText(t, 'x')
        File.Delete(t)
        log(True, 'folder is writable')
    except Exception as e:
        log(False, 'folder write test: %s' % e)


def kayit_defteri_yaz(hedef):
    # the Excel macro remembers the program folder with SaveSetting (HKCU\\Software\\VB and VBA Program Settings); set it to the new folder
    prog = os.path.join(hedef, 'AnalizTakip')
    yol = 'Software\\VB and VBA Program Settings\\AnalizTakip\\Ayar'
    try:
        from Microsoft.Win32 import Registry
        anahtar = Registry.CurrentUser.CreateSubKey(yol)
        anahtar.SetValue('Klasor', prog)
        anahtar.Close()
        log(True, 'Excel macro folder setting saved: %s' % prog)
        return
    except Exception as e:
        debug('registry via .NET failed: %s' % e)
    try:
        import System.Diagnostics
        p = System.Diagnostics.Process()
        p.StartInfo.FileName = 'reg.exe'
        p.StartInfo.Arguments = 'add "HKCU\\' + yol + '" /v Klasor /t REG_SZ /d "' + prog + '" /f'
        p.StartInfo.UseShellExecute = False
        p.StartInfo.CreateNoWindow = True
        p.Start()
        p.WaitForExit(15000)
        log(p.ExitCode == 0, 'Excel macro folder setting via reg.exe (exit %s): %s' % (p.ExitCode, prog))
    except Exception as e:
        log(False, 'registry setting (the macro will ask for the folder instead): %s' % e)


def excel_olustur(hedef):
    xl = None
    try:
        t = Type.GetTypeFromProgID('Excel.Application')
        if t is None:
            log(False, 'Excel is not installed (no Excel.Application COM object)')
            return
        xl = Activator.CreateInstance(t)
        log(True, 'Excel started via COM (version %s)' % xl.Version)
    except Exception as e:
        log(False, 'Excel COM start: %s' % e)
        return
    try:
        xl.DisplayAlerts = False
        xl.Visible = False
        wb = xl.Workbooks.Add()
        ws = wb.Worksheets[1]
        ws.Name = 'Analysis Tracker'
        ws.Range('B2').Value2 = 'Analysis Tracker'
        ws.Range('B2').Font.Size = 20
        ws.Range('B2').Font.Bold = True
        ws.Range('B3').Value2 = 'Click a button. (created by analiz_takip_kurulum_24)'
        ws.Columns[1].ColumnWidth = 3
        ws.Columns[2].ColumnWidth = 40
        log(True, 'workbook and sheet created')
        yol = os.path.join(hedef, EXCEL_ADI)
        makro_var = False
        try:
            vbp = wb.VBProject
            kod = UTF8Encoding(False).GetString(Convert.FromBase64String(''.join(PAYLOAD['makro.txt']))).lstrip(u'\ufeff')
            mod = vbp.VBComponents.Add(1)
            mod.CodeModule.AddFromString(kod)
            makro_var = True
            log(True, 'VBA macro module inserted')
        except Exception as e:
            log(False, 'VBA macro insert (needs "Trust access to the VBA project object model"): %s' % e)
            bilgi('-> open makro.txt in the folder and paste it into Alt+F11 > Insert > Module by hand.')
        if makro_var:
            try:
                dugmeler = [('B5', 40, 'Open Analysis Tracker', 'ProgramiAc'),
                            ('B8', 26, 'Test: does a macro run?', 'TestMakro'),
                            ('B10', 26, 'Test: does PowerShell run?', 'TestPowerShell'),
                            ('B12', 26, 'Select Program Folder', 'KlasorDegistir')]
                for hucre, yuk, metin, makro in dugmeler:
                    r = ws.Range(hucre)
                    b = ws.Buttons().Add(r.Left, r.Top, r.Width, yuk)
                    b.OnAction = makro
                    b.Caption = metin
                log(True, '4 buttons created')
            except Exception as e:
                log(False, 'buttons: %s' % e)
        try:
            if File.Exists(yol):
                File.Delete(yol)
            wb.SaveAs(yol, 52 if makro_var else 51)     # 52 = xlsm, 51 = xlsx
            if makro_var:
                log(True, 'saved as .xlsm: %s' % yol)
            else:
                yol2 = yol.replace('.xlsm', '.xlsx')
                wb.SaveAs(yol2, 51)
                log(True, 'saved WITHOUT macro as .xlsx: %s' % yol2)
        except Exception as e:
            log(False, 'save: %s' % e)
        try:
            xl.Visible = True
            log(True, 'Excel window opened (left open for you)')
        except Exception as e:
            log(False, 'show Excel: %s' % e)
    except Exception as e:
        log(False, 'Excel step: %s' % e)
        bilgi(traceback.format_exc())
        try:
            xl.Quit()
        except Exception:
            pass


def rapor_goster(hedef):
    f = Form()
    f.Text = 'Analysis Tracker - setup test result'
    f.StartPosition = FormStartPosition.CenterScreen
    f.Size = Size(900, 520)
    t = TextBox()
    t.Multiline = True
    t.ReadOnly = True
    t.ScrollBars = ScrollBars.Both
    t.WordWrap = False
    t.Dock = DockStyle.Fill
    t.Font = Font('Consolas', 9.5)
    t.Text = '\r\n'.join(LOG)
    f.Controls.Add(t)
    b = Button()
    b.Text = 'Open folder'
    b.Dock = DockStyle.Bottom
    b.Height = 34

    def ac(s, e):
        try:
            System.Diagnostics.Process.Start('explorer.exe', '"' + hedef + '"')
        except Exception:
            pass
    b.Click += ac
    f.Controls.Add(b)
    f.Show()


def main():
    debug('script started')
    hedef = hedef_sec()
    debug('target = %s' % hedef)
    if not hedef:
        return
    LOG.append('target folder: ' + hedef)
    LOG.append('time: ' + datetime.now().strftime('%Y-%m-%d %H:%M:%S'))
    try:
        dosyalari_yaz(hedef)
        kayit_defteri_yaz(hedef)
        debug('files step done')
        excel_olustur(hedef)
        debug('excel step done')
    except Exception as e:
        log(False, 'unexpected: %s' % e)
        bilgi(traceback.format_exc())
    for yol in (os.path.join(hedef, 'kurulum_test.log'), os.path.join(Path.GetTempPath(), 'kurulum_test.log')):
        try:
            File.WriteAllText(yol, '\r\n'.join(LOG), UTF8Encoding(True))
            LOG.append('log saved: ' + yol)
            break
        except Exception as e:
            LOG.append('log could not be saved to %s: %s' % (yol, e))
    rapor_goster(hedef)


import System
import System.Diagnostics
try:
    main()
except Exception as _e:
    _m = 'Setup test crashed:\r\n%s\r\n\r\n%s' % (_e, traceback.format_exc())
    debug(_m)
    MessageBox.Show(_m, 'Analysis Tracker setup test')
